insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8ae8c1d6-4a69-4a78-8255-8f7a954e4608', 'de', 'Café. Du sagst etwas zur langen Schlange. Sie lächelt, antwortet mit einem Witz und dreht sich zu dir.', '["Sie ist höflich, weil du zuerst etwas gesagt hast", "Sie ist offen und bereit, weiterzureden", "Sie vertreibt sich nur die Wartezeit"]'::jsonb, 'Humor und Zuwendung zeigen Interesse. Sie macht mit, statt nur zu antworten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8ce90839-46ac-4c09-88d3-7e5231bbade8', 'de', 'Du siehst ein cooles Tattoo an ihrem Arm. Welcher Opener zeigt Neugier?', '["„Was ist die Geschichte hinter dem Tattoo? Sieht echt cool aus.“", "„Das Tattoo sieht an dir heiß aus.“", "„Du hast coolen Stil.“", "„Hast du noch mehr Tattoos?“"]'::jsonb, 'Neugier auf ihre Erlebnisse lädt zu einer echten Verbindung ein, ohne Hintergedanken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('90a2ae5f-3f19-4289-983b-90a3660b1de9', 'de', 'Was passiert, wenn jemand höfliche oder kühle Signale ignoriert?', '["Die Anziehung wächst langsam", "Das Wohlgefühl sinkt", "Das Gespräch wird tiefer", "Das Interesse wird klarer"]'::jsonb, 'Wer Signale ignoriert, sorgt für Anspannung und Unbehagen. Geh, sobald du solche Signale bemerkst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('92fc8147-e976-4d33-824a-5ea94444d15c', 'de', 'Warum funktionieren falsche Vermutungen oft trotzdem?', '["Auch eine Korrektur bezieht sie ein und bringt Schwung", "Danebenliegen senkt den Druck", "Frauen korrigieren Männer gern"]'::jsonb, 'Ob du richtigliegst oder nicht: Um zu antworten, muss sie sich einbringen. Genau darum geht es.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94a93921-8975-4a5a-ac8a-918d2cfeb071', 'de', 'Warum solltest du mit Neugier ansprechen?', '["Sie verbirgt die Anziehung", "Sie verhindert Abfuhren", "Sie funktioniert wie ein psychologischer Trick", "Sie senkt den Druck und gibt ihr das Gefühl, interessant zu sein"]'::jsonb, 'Menschen öffnen sich, wenn sie sich gesehen fühlen, nicht bewertet oder gejagt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95d93e33-2d1c-431f-a2f0-0ed76d7c559c', 'de', 'Fitnessstudio. Du sprichst sie an. Sie antwortet freundlich und steckt dann ihre Kopfhörer wieder rein.', '["Offen: Sie hat ausführlich geantwortet und zeigt Interesse", "Höflich: Sie hat aus Höflichkeit geantwortet, will aber nicht weiterreden", "Kühl: unhöfliches Verhalten, das dir sagt, du sollst sofort gehen"]'::jsonb, 'Sie hat dich wahrgenommen und dann eine Grenze gezogen. Zieh dich zurück, ohne es in die Länge zu ziehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('96cd2c07-1109-4ded-b869-cec66cf863b9', 'de', 'Du sprichst sie in einer Bar direkt an. Ihre Freundin kommt dazu, und sie dreht sich leicht zu ihr.', '["Einfach weiterreden wie bisher", "Um Aufmerksamkeit konkurrieren", "Ansprechen, dass sie sich weggedreht hat", "Die Freundin begrüßen oder dich sauber verabschieden"]'::jsonb, 'Feingefühl heißt, dich anzupassen, wenn sich die Situation ändert.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97f948e5-43c9-49fb-91ea-249d0532afa8', 'de', 'Auf einer Party steht sie bei den Getränken. Welcher direkte Opener passt am besten?', '["„Ich hab dich von drüben gesehen und musste dich einfach kennenlernen.“", "„Die Musik ist ganz schön laut, oder?“", "„Weißt du, wo das Bad ist?“", "„Bist du öfter hier?“"]'::jsonb, 'Klar gezeigtes Interesse passt ganz natürlich zu einer Party.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('99e493d5-07b4-4d19-ad59-483e3579a8d1', 'de', 'Was macht einen Opener, der nach ihrer Meinung fragt, wirksam?', '["Er erklärt, warum du gerade sie fragst und nicht irgendwen", "Er macht ihre Sicht wertvoll und wichtig", "Er schafft eine Diskussion, die Spannung und Anziehung aufbaut"]'::jsonb, 'Menschen blühen auf, wenn ihre Sicht zählt. Wertschätzung weckt Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a58e14a-b997-4eae-a453-494d620dffc6', 'de', 'Bar. Du sagst: „Du bist eindeutig die Vernünftige, die am Ende alle nach Hause fährt.“ Was funktioniert hier?', '["Die konkrete Vermutung bringt sie dazu, sofort zu antworten und einzusteigen", "Sie ist neugierig, wie du darauf kommst", "Beides"]'::jsonb, 'Eine konkrete Vermutung verlangt nach einer Antwort und bezieht sie sofort ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9c7e0b10-8bac-4319-8672-b7ce62646374', 'de', 'Du stehst in einer vollen Bar neben ihr. Welche indirekten Opener gibt es?', '["Fragen, ob die Bar immer so voll ist", "Fragen, was sie bestellt", "Ihr sagen, dass sie attraktiv aussieht", "Nach ihrem Instagram fragen"]'::jsonb, 'Beobachtungen zur Umgebung wirken wie Mitmachen, nicht wie Stören.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9cf11184-5b92-4e5e-ac1b-12519aa0d194', 'de', 'Sie lächelt höflich, wendet sich aber nach einer kurzen Antwort wieder ihrem Handy zu. Was zeigt das?', '["Höfliche Duldung, kein echtes Interesse", "Starke Offenheit, schüchtern versteckt", "Eine kühle Abfuhr, bei der du dranbleiben musst", "Eine offene Einladung weiterzumachen"]'::jsonb, 'Ein höfliches Lächeln mit Rückzug zeigt Neutralität, kein Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9fb3d329-54bd-4b72-a37a-6435bb2ff6a4', 'de', 'Du sagst, wie lange es mit den Getränken dauert. Sie lächelt und stimmt begeistert zu.', '["Sie ist genervt und lässt Dampf ab, hat aber nicht unbedingt Interesse", "Sie testet, ob du ihren Beschwerden zustimmst", "Sie erwidert deine Energie und bleibt im Gespräch"]'::jsonb, 'Eine begeisterte Antwort und dass sie beim Thema bleibt, zeigen Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a02bd67f-f7f7-4331-a001-13bf4277f3f7', 'de', 'Warum funktioniert „Ich hab eine Frage“ als Einstieg besser, als die Frage gleich zu stellen?', '["Es zeigt Respekt, weil du um Erlaubnis fragst, bevor du ihre Zeit beanspruchst", "Es baut Vorfreude und Neugier auf, bevor die eigentliche Frage kommt", "Es gibt ihr Zeit, sich innerlich auf das Gespräch einzustellen"]'::jsonb, 'Wenn du die Frage ankündigst, baust du erst Neugier auf. Eine direkte Frage weckt keine Vorfreude.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a08ba78a-da12-481b-ae11-9fc1b34e1ee4', 'de', 'Was ist die wichtigste Erkenntnis darüber, wie Verbindungen entstehen?', '["Einer muss bereit sein, als Erster etwas zu sagen", "Sie entstehen wie von Zauberhand, ganz ohne Zutun", "Warten führt immer zu besseren Ergebnissen", "Schweigen führt zu tieferen Beziehungen"]'::jsonb, 'Jeder Freund, den du hast, ist dein Freund, weil einer von euch zuerst den Mund aufgemacht hat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a0996b03-70aa-45f2-8b9b-1e136e46396e', 'de', 'Du steigst mit einer Bemerkung zur Situation ein. Sie lacht und ergänzt selbst etwas. Dein nächster Schritt?', '["Zu einem direkten Kompliment übergehen", "Beim Thema bleiben und etwas tiefer gehen", "Sofort nach ihrer Nummer fragen", "Sie verspielt aufziehen"]'::jsonb, 'Dass sie etwas beiträgt, zeigt Interesse. Wenn du vertiefst, bleibt der natürliche Schwung erhalten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a2802fe7-bfee-46b8-9b7a-3b8797515730', 'de', 'Café. Sie geht auf dich ein. Der Barista ruft ihren Namen. Sie sagt: „Oh, das bin ich, sorry!“ Was ist das?', '["Offen, aber unterbrochen: Schnell vorschlagen, euch zusammenzusetzen", "Höflich: Sie nutzt das Abholen als bequemen Ausweg", "Störung von außen, kein Signal: Schau, ob sie nach dem Abholen zurückkommt"]'::jsonb, 'Vor der Unterbrechung war Interesse da. Schau, ob sie danach zurückkommt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a281e41d-8c59-42aa-8e23-5071d84c9c8c', 'de', 'Warum funktioniert „Mein Kumpel und ich diskutieren gerade …“ als Einstieg?', '["Es macht neugierig, worum es in der Diskussion geht", "Ihre Meinung entscheidet, und dadurch fühlt sie sich geschätzt", "Es zeigt sozialen Beweis, weil du Freunde hast"]'::jsonb, 'Eine kleine Streitfrage lädt sie ein, ihre Meinung zu sagen. So fühlt sie sich geschätzt und einbezogen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a445b565-f83a-4031-9b70-7201a9b11bc3', 'de', 'Was signalisierst du, wenn du die Richtung des Gesprächs vorgibst?', '["Selbstbewusstsein", "Führung", "Orientierung", "Alle oben genannten"]'::jsonb, 'Wenn du das Thema wählst, zeigst du Selbstbewusstsein und Führung. Gib die Richtung vor, statt zu warten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a51060bf-7646-4967-a8bf-730e53f6714d', 'de', 'Warum weckt „Hi, ich hab eine Frage an dich“ so gut Neugier?', '["Es erzeugt Ungewissheit: Sie will wissen, was die Frage ist", "Es zeigt Selbstbewusstsein, weil du sie bei etwas unterbrichst", "Es zeigt, dass du etwas brauchst, und sie wird weniger vorsichtig"]'::jsonb, 'Wenn eine Information unvollständig ist, will das Gehirn sie ergänzen. Nutz das, um Aufmerksamkeit zu wecken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a95654fc-2f4a-4b06-a6d7-ce66be1aaac1', 'de', 'Ihr stöbert beide in einem Buchladen. Welche indirekten Opener gibt es?', '["Fragen, ob sie dieses Buch kennt", "Ihr sagen, dass sie dir aufgefallen ist", "Nach ihrer Nummer fragen", "Etwas dazu sagen, wie gut der Autor ist"]'::jsonb, 'Opener, die eine Beobachtung aufgreifen, fügen sich in den Moment ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ab9eedd4-bf67-486a-8b3c-938ef10f4137', 'de', 'Warum ist es sinnvoll anzusprechen, statt stillzuhalten?', '["Nichtstun garantiert das Scheitern, Handeln schafft Möglichkeiten", "Ansprechen baut schneller Anziehung auf", "Handeln garantiert Selbstbewusstsein"]'::jsonb, 'Wenn du nichts tust, kann nichts passieren. Wenn du handelst, kann etwas passieren.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ad29d82a-7cad-4f44-8cd0-826bc8d6d751', 'de', 'Ein Typ bleibt auf einer Party still, während andere ins Gespräch kommen. Was fehlt ihm?', '["Besseres Timing", "Sozialer Status", "Freunde zum Reden", "Die Bereitschaft, auf andere zuzugehen"]'::jsonb, 'Ein Gespräch anzufangen ist der einfache Schritt, aus dem Verbindung entsteht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ada0ea94-3879-4702-b335-f62a57dd6045', 'de', 'Warum werden höfliche Reaktionen so leicht als Interesse missverstanden?', '["Sie enthalten Blickkontakt und Freundlichkeit", "Frauen vermeiden schroffe Abfuhren", "Männer deuten ihr eigenes Verlangen in neutrale Signale hinein", "Alle oben genannten"]'::jsonb, 'Höfliche Signale sind bewusst sanft. Verlass dich lieber auf anhaltende Aufmerksamkeit und Gegenfragen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ae78311f-d702-432d-971c-a612871a0e09', 'de', 'Sie lächelt dich leicht an und dreht sich dann weg. Was rät die Drei-Sekunden-Regel?', '["Ihr Lächeln auf Interesse hin analysieren", "Auf ein deutlicheres Zeichen warten", "Sofort hingehen, bevor du ins Grübeln kommst", "Erst sorgfältig deine Worte planen"]'::jsonb, 'Schnelles Handeln kommt der wachsenden Liste an Gründen zuvor, die dein Kopf gegen das Hingehen sammelt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b147a697-dedb-4919-b533-e070ef0767f6', 'de', 'Wie vermeidest du, dass automatisch eine Bedrohungsreaktion ausgelöst wird?', '["Aus einem Winkel kommen, in dem sie dich sieht", "Ihr keine Wege oder Bewegungsmöglichkeiten versperren", "In respektvollem Abstand stehen bleiben", "Alle oben genannten"]'::jsonb, 'Wenn du ihren persönlichen Raum respektierst, wirkt das Gespräch ruhig und natürlich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b22764cf-ce02-4bf8-8eb7-5fb7926333ed', 'de', 'Ihr Buch hat ein interessantes Cover. Womit könntest du einsteigen, um sie neugierig zu machen?', '["„Was ist das für ein Buch?“", "„Liest du viel?“", "„Das sieht interessant aus.“", "„Ich muss dich was zu dem Buch fragen, das du da hast.“"]'::jsonb, 'Die Ankündigung macht neugierig, bevor du die eigentliche Frage stellst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b2eb7c50-c714-4003-a310-0084c29f7fcc', 'de', 'Warum nehmen indirekte Opener Druck raus?', '["Es sind eingeübte Sätze, die in vielen Situationen funktionieren", "Sie muss nicht sofort entscheiden, ob sie dich attraktiv findet", "Sie verstecken deine Absicht hinter einem lockeren, glaubwürdigen Gespräch"]'::jsonb, 'Indirekte Opener fühlen sich an wie eine Fortsetzung des Moments, in dem ihr beide schon seid.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b32bbd22-abe6-4fd4-9f13-deaaad94298d', 'de', 'Sie hat eine Handyhülle mit Pflanzenmotiv. Welcher Opener zeigt Neugier?', '["„Süße Hülle.“", "„Gärtnerst du?“", "„Dein Handy sieht schön aus.“", "„Stehst du auf Pflanzen? Da sind ein paar coole auf der Hülle.“"]'::jsonb, 'Neugier auf ihre Erlebnisse lädt zu einer echten Verbindung ein, ohne Hintergedanken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b58b39df-93ba-4f7a-bed5-8eaaa5aa7a37', 'de', 'Sie tanzt mit Freundinnen. Ihr habt Blickkontakt, und sie lächelt. Was tust du?', '["Warten, bis sie eine Tanzpause macht", "In ihrer Nähe anfangen zu tanzen", "Noch mal Blickkontakt suchen, bevor du losgehst", "Zu ihr und der Gruppe hingehen"]'::jsonb, 'Abends ändert sich die Situation schnell. Wer zögert, macht aus Signalen verpasste Chancen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b5ec6ba9-5bbb-4681-a239-50a711d681dd', 'de', 'Warum funktionieren Opener mit einer Streitfrage so gut?', '["Sie schaffen einen verspielten Konflikt, der sexuelle Spannung aufbaut", "Ihre Meinung entscheidet die Frage, und dadurch fühlt sie sich wichtig", "Sie zeigen sozialen Beweis (du hast mit einem Kumpel geredet)"]'::jsonb, 'Eine kleine Streitfrage lädt sie ein, ihre Meinung zu sagen. So fühlt sie sich geschätzt und einbezogen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b723c51c-c180-4bd0-900c-be66fdc3c190', 'de', 'Was ist der größte Unterschied zwischen Höflichkeit und Offenheit?', '["Der Tonfall", "Wie oft sie lächelt", "Wie sehr ihr euch beide einbringt", "Die körperliche Nähe"]'::jsonb, 'Offenheit heißt mitmachen und neugierig sein. Höflichkeit heißt, die Situation angenehm zu halten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b765cb2c-14d9-49bf-b793-eeb611ababea', 'de', 'Was passiert, wenn du nur unter perfekten Bedingungen ansprichst?', '["Jedes Ansprechen fühlt sich wichtiger an, weil es so selten ist", "Du sprichst viel seltener an, als wenn du ständig auf Leute zugehst", "Deine Ansprachen werden besser, weil du wählerisch bist"]'::jsonb, 'Wer auf perfekte Bedingungen wartet, spricht seltener an, und jedes Mal steht mehr unter Druck.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b76c6af0-9df1-46cb-92cc-9c07b2d1404f', 'de', 'Warum nimmt ein Zeitlimit so wirksam Druck raus?', '["Sie weiß, dass sie nicht in einem endlosen Gespräch mit einem Fremden feststeckt", "Es zeigt, dass du ihre Zeit respektierst und nicht verschwendest", "Bei wenig Zeit ist das Risiko einer peinlichen Abfuhr geringer"]'::jsonb, 'Wenn du sagst, dass du nicht lange bleibst, nimmt das Druck raus. Setz es gleich am Anfang ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b86940dc-da66-4fd6-a19f-bbbca988a036', 'de', 'Welche körperlichen Anpassungen sorgen dafür, dass du weniger Nervosität ausstrahlst?', '["Gleichmäßig gehen, weder hastig noch zögerlich", "Die Schultern locker nach hinten und unten, nicht hochgezogen oder gekrümmt", "Die Frau fixieren, um Fokus und Absicht zu zeigen"]'::jsonb, 'Ein gleichmäßiges Tempo und lockere Schultern verringern sichtbare Anspannung, bevor du etwas sagst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ba3e426f-7282-4d49-a10f-46c3512816fc', 'de', 'Sie reagiert neutral, du machst einen klaren Schritt, und sie sagt Nein. Was solltest du tun?', '["Dich bedanken und ruhig gehen", "Es anders formulieren und noch mal versuchen", "Dein Interesse rechtfertigen", "Das Thema wechseln"]'::jsonb, 'Ein Nein ist eine klare Grenze. Nimm es ruhig an und geh gelassen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bb7584e8-d1df-4dc9-a2bf-59a289ba6852', 'de', 'Was passiert, wenn du nur reagierst, statt die Richtung vorzugeben?', '["Das Gespräch brauchte einfach mehr Zeit, um voranzukommen", "Du gibst den Rahmen ab, und sie wird den nächsten Schritt nicht für dich machen", "Das Timing verbessert sich, bevor du weitergehst"]'::jsonb, 'Wenn du nicht mehr führst, verliert das Gespräch an Schwung. Ergreif die Initiative und bring es voran.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc490fe2-1fae-42f6-b95e-718da8dccc05', 'de', 'Warum ist es für ein respektvolles Gespräch so wichtig, früh Signale zu lesen?', '["Ihr erstes Verhalten zeigt, wie viel Spielraum du zum Weitermachen hast", "Frauen müssen sich sicher fühlen, bevor sie Interesse zeigen können", "Frühe Signale verhindern, dass du Grenzen überschreitest, die sie nicht geöffnet hat", "Alle oben genannten"]'::jsonb, 'Ihr Wohlgefühl kommt zuerst. Nutz die Signale, um zu entscheiden, ob du weitermachst oder dich zurücknimmst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc5cb121-8a63-45f6-8e11-7d46e1ff9ec2', 'de', 'Welche Eigenschaften stärken den Rahmen eines Mannes?', '["Klarer Glaube an sich selbst", "Gelassenheit gegenüber Abfuhren", "Die Richtung vorgeben", "Nach Bestätigung suchen"]'::jsonb, 'Klarer Glaube an dich selbst und Führung stärken deinen Rahmen. Vermeide alles, was nach Zustimmung heischt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c1dd9ccd-317b-4320-a1f4-5bbb6553f846', 'de', 'Du sprichst sie an. Sie lächelt, dreht sich zu dir und fragt freundlich: „Was gibt’s?“', '["Offen: Sie ist offen. Bau das Gespräch weiter auf", "Höflich: Sie ist nur freundlich. Teste erst mit einem weiteren Satz", "Unklar: Du brauchst mehr Infos, um ihr Interesse einzuschätzen"]'::jsonb, 'Wenn sie sich mit Fragen und offener Haltung einbringt, ist Interesse da. Halt den Schwung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c229e235-368e-47aa-9571-c1345d6402cf', 'de', 'Du sprichst eine Frau im Café an. Mit welchem Opener fühlt sie sich geschätzt?', '["„Hi, bist du öfter hier?“", "„Ich brauch mal die Meinung einer Frau.“", "„Was trinkst du da?“", "„Du siehst heute gut aus.“"]'::jsonb, 'Wenn du ausdrücklich nach ihrem Urteil fragst, wird sie wichtig, und das weckt ihr Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c321230f-a277-4593-bdeb-01167899a30c', 'de', 'Supermarkt. Du sagst: „Du wirkst wie ein totaler Gesundheitsfreak. Stimmt’s?“ Sie lacht. Was funktioniert hier?', '["Die verspielte Vermutung hat sie einbezogen und sofort Geplänkel erzeugt", "Du hast mit einer mutigen Aussage Selbstbewusstsein gezeigt", "Du hast sie neugierig gemacht, warum du sie für gesundheitsbewusst hältst"]'::jsonb, 'Lachen plus Korrektur heißt, sie ist dabei. Bleib in diesem verspielten Rahmen und bau ihn aus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c36a094c-8b8b-4c97-b801-f551071a78ed', 'de', 'Sie trägt künstlerische Vintage-Kleidung. Welcher Opener nutzt eine Vermutung wirksam?', '["„Ich liebe deinen Stil. Wo kaufst du normalerweise ein?“", "„Du siehst aus, als würdest du was Kreatives machen. Stimmt’s?“", "„Du gehst bestimmt oft in Secondhandläden, oder?“", "B oder C"]'::jsonb, 'Bei beiden muss sie sich einbringen, um zu bestätigen, zu widersprechen oder zu erklären.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c387493a-0ebd-41c3-b083-1a639c5a593d', 'de', 'Warum schwächt eine frühe Entschuldigung deinen Opener?', '["Sie senkt deinen Status", "Sie zeigt, dass du störst", "Sie gibt ihr die Kontrolle", "Alle oben genannten"]'::jsonb, 'Wer sich entschuldigt, stellt sich als Störung dar. Steig lieber so ein, als gehörtest du dazu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3fe310a-e657-4693-8a1b-acee8218f2a8', 'de', 'Welche Regel lässt einen Opener mit einer Vermutung aufmerksam statt beliebig wirken?', '["Ihn selbstbewusst rüberbringen", "Ihn auf etwas stützen, das man sehen kann", "Ihn vage halten", "Ihn herausfordernd formulieren"]'::jsonb, 'Wenn deine Vermutung auf sichtbaren Hinweisen beruht, wirkt sie durchdacht statt willkürlich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c41c83a5-d2fe-4cdf-b37f-bcec922ef1d8', 'de', '„Mein Kumpel hält mich für verrückt, aber ich finde, Leute, die …“ Was bewirkt dieser Opener?', '["Er schafft eine Streitfrage, bei der ihre Meinung entscheidet", "Er zeigt Persönlichkeit und Humor, um Anziehung aufzubauen", "Er macht sie misstrauisch, weil du sie anbaggerst"]'::jsonb, 'Eine kleine Streitfrage lädt sie ein, ihre Meinung zu sagen. So fühlt sie sich geschätzt und einbezogen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c4e94987-68b3-4c33-b481-27950bb88e63', 'de', 'Wo passen direkte Opener am besten?', '["Im Supermarkt", "In ruhigen Bibliotheken", "Im Wartezimmer beim Arzt", "In Bars und Clubs"]'::jsonb, 'Direktes Interesse passt an Orte, an denen man ohnehin flirtet, zum Beispiel Bars und Clubs.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c4ec10a6-7307-4d33-b4ac-bab091417d95', 'de', 'Warum schwächt eine Entschuldigung im Opener deinen Rahmen?', '["Sie geht davon aus, dass das, was sie gerade tut, wichtiger ist", "Sie fragt um Erlaubnis, statt zu führen", "Sie stellt deine Anwesenheit als Störung dar", "Sie zeigt, dass du den Moment selbstbewusst in der Hand hast"]'::jsonb, 'Eine Entschuldigung macht dich zur Störung statt zu einer Option.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c728f4f6-0836-4faf-b386-b10c475ae132', 'de', 'Warum machen indirekte Opener weniger Druck als direkte?', '["Sie zeigen sofort romantisches Interesse", "Sie lassen die Ansprache wie einen zufälligen gemeinsamen Moment wirken", "Sie lassen das Gespräch sich natürlich entwickeln", "Sie verstecken die Absicht hinter einer Bemerkung zur Situation"]'::jsonb, 'Eine gemeinsame Situation lässt den Einstieg naheliegend wirken, und es fällt leicht, darauf einzugehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c9f1e798-7318-4c31-b9db-3d51fbde0554', 'de', 'Was ist der Hauptgrund, warum Opener mit einer Vermutung sie ins Gespräch ziehen?', '["Sie wirken selbstbewusster als Fragen", "Sie zeigen früh romantisches Interesse", "Sie verlangen eine aktive Antwort statt einer Antwort auf Autopilot"]'::jsonb, 'Eine Vermutung verlangt nach einer Antwort. Sie ist sofort dabei, zu korrigieren oder zu bestätigen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cad92129-8727-4718-bff9-4ab66c366d32', 'de', 'Warum ziehen Opener, die nach ihrer Meinung fragen, sie von Anfang an so ins Gespräch?', '["Sie geben ihr das Gefühl, dass ihre Sicht wichtig ist", "Sie zeigen sie als jemanden, dessen Urteil zählt", "Sie sind rein zweckmäßig und schnell abgehakt", "Sie helfen, weil sie ihren Beitrag wertschätzen"]'::jsonb, 'Menschen reagieren, wenn sie sich gehört und ernst genommen fühlen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cb1b3910-7f46-4638-b7ba-949483f7d10a', 'de', 'Bar. Ihr seid in eine ruhigere Ecke gegangen. Was kommt als Nächstes?', '["Weiterreden und vorschlagen, euch ein andermal zu treffen", "Jetzt ihre Nummer holen, solange der Schwung da ist", "Noch einen Ortswechsel vorschlagen oder körperlich näherkommen", "B oder C, je nach Umständen und ihren Signalen"]'::jsonb, 'Bei starkem Schwung solltest du weitergehen: Entweder sicherst du dir den Kontakt, oder du bringst die Begegnung voran.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ccb554b7-2aa7-47d7-a64b-d4d9612a37a1', 'de', 'Warum lösen bestimmte Winkel und Abstände beim Ansprechen Unbehagen aus?', '["Sie lösen automatisch eine Bedrohungsreaktion aus", "Sie versperren mögliche Wege oder Ausgänge", "Sie machen deine Absicht beim Herangehen unsichtbar", "Sie zeigen immer großes Selbstbewusstsein"]'::jsonb, 'Ein ungünstiger Winkel und zu wenig Abstand wirken aufdringlich, noch bevor sie bewusst entscheiden kann.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cd75e2e6-d17a-4bb7-93e9-0f592f46fef8', 'de', 'Warum muss dein Rahmen interessanter sein als das, was sie vorher gemacht hat?', '["Sonst kehrt sie dazu zurück", "Menschen achten von Natur aus auf das, was interessant ist", "Du musst ihre Aufmerksamkeit gewinnen, gegen alle Ablenkungen", "Alle oben genannten"]'::jsonb, 'Alles richtig: Wenn dein Rahmen nicht spannender ist als das, was sie gerade tut, kehrt sie dazu zurück.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ceadc18e-3007-4ed0-beba-55eb062fbd75', 'de', 'Das Gespräch läuft gut. Sie fragt, woher du kommst. Du antwortest. Und dann?', '["Ihr eine andere Frage stellen, um die Führung zu behalten", "Deine Antwort ausführlich erklären, um weiterzureden", "Sie die nächste Frage stellen lassen, um zu zeigen, dass du zuhörst"]'::jsonb, 'Den Rahmen setzen heißt, das Gespräch voranzubringen. Antworte und lenk dann weiter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cf063d07-0835-4825-9d56-79f6e3255038', 'de', 'Du sagst ihr, dass du sie attraktiv findest. Sie bedankt sich, antwortet aber knapp.', '["Noch einen draufsetzen, um Selbstbewusstsein zu zeigen", "Zu Smalltalk wechseln, um die Anspannung zu lösen", "Höflich abschließen und sie in Ruhe lassen"]'::jsonb, 'Knappe Antworten, nachdem du deine Absicht klar gezeigt hast, heißen: Das Interesse ist nicht gegenseitig.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d0ec47ae-1140-4d62-b956-39af81780946', 'de', 'Welches Verhalten zeigt, dass du den Rahmen klar setzt?', '["Ruhige Gewissheit", "Unentschlossenheit", "Übergänge selbst gestalten", "Zustimmung brauchen"]'::jsonb, 'Den Rahmen hältst du durch Richtung, nicht durch Zustimmung. Führ, statt dich ständig rückzuversichern.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d1f7d186-8772-4b75-bb24-e34679605860', 'de', 'Ihr seid beide mit Hunden unterwegs, die anfangen, miteinander zu spielen. Was funktioniert als indirekter Einstieg?', '["Etwas dazu sagen, wie gut sich die Hunde verstehen", "Sie oder ihren Hund für das Aussehen loben", "Fragen, was für eine Rasse ihr Hund ist", "Fragen, ob sie oft in diesen Park kommt"]'::jsonb, 'Wenn du beim gemeinsamen Erlebnis bleibst, kann sich ganz natürlich Vertrautheit aufbauen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d3daff27-e652-43a8-8f20-af94b5be0f32', 'de', 'Auf der Straße. Sie ist freundlich, aber du bist unsicher, ob sie Interesse hat. Was ist der beste nächste Schritt?', '["Neben ihr hergehen und weiterreden", "Deine Energie runterfahren und dich ihrem Tempo anpassen", "Sagen: „Du wirkst cool. Lust, mal einen Kaffee trinken zu gehen?“"]'::jsonb, 'Eine einfache Einladung lässt ihr klar die Wahl, ja oder nein zu sagen, ohne dass du das Gespräch erzwingst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d43846a5-78ac-402f-95a0-7cfcb54078ce', 'de', 'Warum ist es nach neutralen Reaktionen besser, Klarheit zu schaffen, statt herumzutrödeln?', '["Sie kann klar Ja oder Nein sagen", "Peinliches Herumstehen wird kürzer", "Sie wird gezwungen, ihre Anziehung zu zeigen", "Du musst nicht mehr raten"]'::jsonb, 'Ein klarer Satz räumt Unklarheit aus und zeigt, ob hinter ihrer Freundlichkeit Interesse steckt oder nur Höflichkeit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d466b22a-5014-4620-9cfa-19217d091ad6', 'de', 'Welche indirekten Opener funktionieren gut?', '["Etwas zur Umgebung sagen", "Nach der Situation fragen, in der ihr beide seid", "Gemeinsame Erlebnisse aufgreifen", "Ihr Aussehen loben"]'::jsonb, 'Eine gemeinsame Situation lässt den Einstieg naheliegend wirken, und es fällt leicht, darauf einzugehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d61d2413-5ee2-43c8-8cce-8d6030c1879e', 'de', 'Was zerstört deinen Rahmen schon im Opener?', '["Eine klare Aussage machen, statt um Erlaubnis zu fragen", "Dich entschuldigen, dass du sie ansprichst oder störst", "Erst fragen, ob es okay ist, mit ihr zu reden"]'::jsonb, 'Wer sich entschuldigt, stellt sich als Störung dar. Steig lieber so ein, als gehörtest du dazu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d743d469-5774-4931-80b8-cf68fa8054d1', 'de', 'Du zögerst 30 Sekunden, und jemand anderes spricht sie zuerst an. Woran lag das?', '["Du hast deinem Kopf Zeit gegeben, es dir auszureden", "Dir fehlte ein guter Opener", "An ihrem klaren Desinteresse", "Du hast dich nicht bereit genug gefühlt"]'::jsonb, 'Schnelles Handeln verhindert, dass Zweifel aufkommen. Geh los, spätestens drei Sekunden nachdem du sie bemerkt hast.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d76f2c05-59de-4480-a3a4-8dbe27fb2854', 'de', 'Warum funktioniert die Drei-Sekunden-Regel?', '["Sie gibt dir Zeit, einen perfekten Opener vorzubereiten", "Sie lässt dich erst ihr Interesse einschätzen", "Du handelst, bevor dein Alarmsystem Widerstand aufbaut"]'::jsonb, 'Die Regel wirkt, weil du handelst, bevor dein Kopf Gründe dagegen findet.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('daf41a36-31b3-4cc7-b731-be0601f73a66', 'de', 'Warum gewinnen Neugier-Opener die Aufmerksamkeit besser?', '["Neugier senkt die Abwehr", "Neugier erzeugt eine Verpflichtung", "Neugier schiebt das Urteil auf", "Neugier weckt Interesse"]'::jsonb, 'Neugier wirkt, weil sie ganz natürlich Aufmerksamkeit anzieht. Steig mit etwas ein, das neugierig macht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc0ff18e-1928-43e2-b403-e3cb7a6b3ab2', 'de', 'Das Gespräch landet bei einem langweiligen Thema. Den Rahmen setzen heißt:', '["Ihr folgen, um zu zeigen, dass du zuhörst und interessiert bist", "Auf ein Thema umlenken, das du spannender findest, ohne ihres abzuwerten", "Ihr sagen, dass du lieber über etwas anderes reden würdest"]'::jsonb, 'Lenk um, indem du auf das Gesagte eingehst und dann zu Themen mit mehr Energie steuerst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc4c48ee-7f80-40c8-8355-cfd7dfdf8159', 'de', 'Café. Du sprichst sie an. Sie lächelt herzlich, antwortet aber knapp und wendet sich ab.', '["Offen: Das herzliche Lächeln zeigt Interesse, trotz der knappen Antworten", "Höflich: Sie lächelt aus Nettigkeit, aber ihre Körpersprache zeigt Zurückhaltung", "Unklar: Bei gemischten Signalen musst du länger reden, um sie einzuschätzen"]'::jsonb, 'Wenn die Antworten knapp sind und sie sich abwendet, respektier die Grenze und geh.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ddf26019-643c-48e3-99bd-8ed12168ae51', 'de', 'In der Bahn liest eine Frau ein Buch, das du liebst. Was garantiert, dass nichts draus wird?', '["Ansprechen und eine Abfuhr bekommen", "Zögern und sie gar nicht ansprechen", "Warten, bis sie zuerst etwas sagt", "Lächeln, aber nichts sagen"]'::jsonb, 'Nichtstun heißt null Chance. Handeln schafft Möglichkeiten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('df7b348f-77a6-43b4-b9c2-72ba495cd148', 'de', 'Sie lächelt, antwortet und stellt dir eine Gegenfrage. Was tust du am besten?', '["Schnell einen Schritt weitergehen", "Das Gespräch verlangsamen", "Ihr ein Kompliment machen", "Ganz natürlich weitermachen"]'::jsonb, 'Wenn sie auf dich eingeht, mach natürlich weiter und bau Schwung auf, ohne das Tempo zu erzwingen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e0a819cd-0a51-464f-ae01-bb50bf45ca1b', 'de', 'Du sagst Hallo. Sie nennt ihren Namen, hält Blickkontakt und fragt, woher du kommst.', '["Sie ist offen und bringt sich ins Gespräch ein", "Sie ist höflich und hält sich an soziale Regeln", "Sie sammelt Infos, um später zu entscheiden"]'::jsonb, 'Dass sie ihren Namen nennt und nachfragt, zeigt aktives Interesse, keine bloße Höflichkeit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e0b6a830-3f63-4d2b-b958-5db45a154beb', 'de', 'Warum verwechseln Männer so oft Höflichkeit mit Offenheit?', '["Männer wollen Interesse sehen und überinterpretieren höfliches Verhalten", "Frauen lernen, höflich zu sein, und Männer halten das für Anziehung", "Höfliche Signale enthalten Lächeln und Wärme, die Männer als Interesse lesen", "Alle oben genannten"]'::jsonb, 'Höfliche Signale sind bewusst sanft. Verlass dich lieber auf anhaltende Aufmerksamkeit und Gegenfragen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e1d6b84b-cc78-420d-8d46-30d10f8f2b0a', 'de', 'Sie ist herzlich, berührt deinen Arm und stellt Fragen, sagt dann aber: „Mein Uber ist da.“', '["Offen, aber mit Zeitlimit: Tausch Kontakte aus, bevor sie einsteigt", "Höflich: Berührung und Fragen waren nur Höflichkeit vor dem geplanten Abgang", "Gemischt: Sie hat ein Zeitlimit genannt"]'::jsonb, 'Starkes Interesse plus echtes Zeitlimit heißt: Tauscht sofort Nummern aus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e2a6f6e8-963f-4da4-bfc3-a9cc1b615ab4', 'de', 'Welche Signale zeigen, dass sie offen und interessiert ist?', '["Sie antwortet knapp, hält aber festen Blickkontakt", "Sie wendet sich dir beim Antworten ganz zu", "Sie stellt Gegenfragen oder bringt selbst etwas ins Gespräch ein"]'::jsonb, 'Wenn sie sich mit Fragen und offener Haltung einbringt, ist Interesse da. Halt den Schwung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e2e4a209-5fc0-4faf-a13c-67ed31a8a170', 'de', 'Du sprichst nur an, wenn du bereit bist und extra dafür losziehst. Was schränkt das ein?', '["Wie oft du insgesamt übst", "Deine Chancen auf perfekte Begegnungen", "Deine Ansprüche an dein Aussehen"]'::jsonb, 'Wenn du nur ausgewählt ansprichst, übst du wenig, und deine Fähigkeiten entwickeln sich langsamer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e3b36edc-fa81-4ae9-ba6b-80b396e930c4', 'de', 'Warum wirken auch falsche Vermutungen?', '["Sie korrigiert dich vielleicht, und auch das ist ein Gespräch", "Ihre Korrektur führt oft dazu, dass sie erzählt, wie es wirklich ist", "Danebenliegen zeigt Verletzlichkeit, und das baut Vertrauen auf"]'::jsonb, 'Falsche Vermutungen bringen sie ins Gespräch, weil sie korrigiert und erklärt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e549d946-f5c9-48d5-8ed3-03653b7ab3b6', 'de', 'Ihr stöbert beide in einem ruhigen Buchladen. Welcher Opener nimmt Druck raus?', '["„Du wirkst wie eine Leseratte.“", "„Mit Buch siehst du gut aus.“", "„Krieg ich deine Nummer?“", "„Hast du hier in letzter Zeit was Gutes gelesen?“"]'::jsonb, 'Eine gemeinsame Situation bringt ein Gespräch ganz natürlich in Gang.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e5eae06f-7a14-4c9f-ab68-d799aa9f603d', 'de', 'Sie reagiert positiv, sagt aber: „Ich muss gleich zurück zu meinen Freundinnen.“ Dein Zug?', '["Offene Reaktion heißt: weitermachen, trotz des genannten Zeitlimits", "In der kurzen Zeit einen starken Eindruck machen und sie dann gehen lassen", "Respektieren: Kurz darauf eingehen, dann sauber verabschieden oder schnell Kontakte tauschen"]'::jsonb, 'Offenheit hebt ein Zeitlimit nicht auf. Halt es kurz oder geh schnell zum nächsten Schritt über.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e6f7a034-55b9-4303-a1f2-e70269b09f81', 'de', 'Du siehst eine Frau mit kunstvollen Tattoos. Welcher Opener bringt sie ins Gespräch?', '["„Hi, wie geht’s dir heute Abend?“", "„Du siehst aus, als würdest du in einem kreativen Bereich arbeiten.“", "„Was machst du beruflich?“", "„Du siehst gut aus.“"]'::jsonb, 'Eine konkrete Vermutung bringt sie dazu, sich einzubringen und persönlich zu antworten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ea6aac0e-0b64-4be8-aa43-1990315262e0', 'de', 'Du sagst: „Du bist wunderschön, ich musste einfach Hallo sagen.“ Sie wird rot und bedankt sich, antwortet aber knapp.', '["Ihr noch ein Kompliment machen, um weiter Interesse zu zeigen", "Sie wegen ihrer Schüchternheit aufziehen, damit sie sich wohler fühlt", "Dich elegant verabschieden: Wenn sie nach einem direkten Opener kaum auf dich eingeht, hat sie kein Interesse"]'::jsonb, 'Rot werden kann Höflichkeit sein. Knappe Antworten nach einem direkten Opener heißen: kein Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ed852bcc-77f4-436a-9582-103cc2537be6', 'de', 'Du sagst: „Ich hab dich gesehen und wollte Hallo sagen.“ Sie lacht, sagt Hallo und fragt, was du machst.', '["Sie ist in Gesellschaft einfach nur höflich", "Sie geht auf dich ein und will weiterreden", "Sie ist überrascht und gewinnt Zeit, um dich einzuschätzen"]'::jsonb, 'Lachen und eine Gegenfrage zeigen, dass sie auf dich eingeht und wirklich weiterreden will.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f0dd9eca-d510-4237-8ce4-290954082900', 'de', 'Was macht deinen Rahmen interessanter als das, was sie gerade tut?', '["Verspielte Vermutungen, die sie sofort einbeziehen", "Nach ihrer Meinung zu etwas fragen, das sie spannend findet", "Lauter oder energiegeladener sein als ihre Umgebung"]'::jsonb, 'Interesse entsteht durch Einbeziehen, nicht durch Lautstärke.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f17c4317-4ac6-4db1-838b-c39a93c3de0f', 'de', 'Bar. Sie ist freundlich, aber du bist unsicher, ob sie Interesse hat. Was ist der beste nächste Schritt?', '["Fragen: „Kommst du mit, was trinken?“", "Körperlich mutig einen Schritt weitergehen", "Tiefere Fragen stellen, um eine Verbindung aufzubauen", "Schweigend abwarten, ob sie wieder einsteigt"]'::jsonb, 'Eine einfache Einladung lässt ihr klar die Wahl, ja oder nein zu sagen, ohne dass du das Gespräch erzwingst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f2b0e5af-f8e1-480b-aa9a-969dfa406d42', 'de', 'Sie dreht sich zu dir, lächelt herzlich, antwortet ausführlich und richtet beim Reden ihre Haare.', '["Sehr offen: Zuwendung, Lächeln, ausführliche Antworten und die Haare zeigen alle Interesse", "Höflich: Sie ist freundlich, und das mit den Haaren ist Zufall", "Nervös: Sie ist wegen des Gesprächs aufgeregt, aber nicht unbedingt interessiert"]'::jsonb, 'Mehrere positive Signale zusammen zeigen Offenheit. Mach weiter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f2ebba26-20ab-4f42-bd4e-eda08aa656ef', 'de', 'Warum schwächt eine Entschuldigung zum Einstieg das Gespräch?', '["Schlechtes Timing", "Schwache Anziehung", "Du stellst dich als Störung dar", "Sie war nicht Single"]'::jsonb, 'Wer sich entschuldigt, stellt sich als Störung dar. Steig lieber so ein, als gehörtest du dazu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fb2737de-57ac-46ae-bfd8-662497358e2a', 'de', 'Warum hilft etwas Geheimnisvolles beim Rahmen?', '["Sie weiß nicht, was du als Nächstes sagst, und das weckt Neugier und Aufmerksamkeit", "Sie kann dich nicht so schnell in eine Schublade stecken und abhaken", "Frauen fühlen sich von Natur aus zu geheimnisvollen Männern hingezogen"]'::jsonb, 'Etwas Geheimnisvolles macht neugierig darauf, was als Nächstes kommt, und fesselt die Aufmerksamkeit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fdbb58fb-2105-465e-9bb2-95117c0d4ee4', 'de', 'Sie dreht sich ganz zu dir und lächelt, sagt aber: „Ich hab heute eigentlich keine Lust, mit Leuten zu reden.“', '["Höfliche Absage: Trotz positiver Körpersprache zeigen ihre Worte kein Interesse", "Test: Sie will sehen, ob du trotz ihres Einwands dranbleibst", "Gemischt: Der Körper sagt Ja, die Worte Nein. Geh sanft darüber hinweg"]'::jsonb, 'Freundliche Körpersprache hebt eine ausgesprochene Grenze nicht auf. Nimm sie an und geh.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fdbdc05b-610e-4954-bace-34af89e1f619', 'de', 'Nach einem direkten Opener lacht sie kurz, schaut sich aber sofort im Raum um.', '["Mehr Energie reinlegen, um ihre Aufmerksamkeit zurückzuholen", "Nach ihrer Nummer fragen, bevor der Schwung weg ist", "Das Gespräch auf natürliche Weise enden lassen"]'::jsonb, 'Lachen kann Höflichkeit sein. Geteilte Aufmerksamkeit heißt: Zeit, dich zurückzuziehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ff750d3c-1bf6-4368-bb6c-04dc1b70a29b', 'de', 'Warum wirkt ein Zeitlimit psychologisch?', '["Das Gehirn entspannt sich, wenn der Moment sich nicht nach langer Verpflichtung anfühlt", "Sie wird weniger vorsichtig, weil sie weiß, dass sie nicht in einem endlosen Gespräch feststeckt", "Es erzeugt Knappheit, durch die du wertvoller wirkst"]'::jsonb, 'Ein Zeitlimit nimmt ihr die Angst, festzustecken, und sie fühlt sich wohler.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
